private void enlarge(final int size) {
    // If the internal byte array is null, initialize it to the requested size.
    if (bytes == null) {
        bytes = new byte[size];
        return;
    }

    // If the current capacity is sufficient, do nothing.
    if (bytes.length >= size) {
        return;
    }

    // Allocate a larger array (double the current size or at least the requested size)
    int newCap = Math.max(bytes.length * 2, size);
    byte[] newBytes = new byte[newCap];
    System.arraycopy(bytes, 0, newBytes, 0, bytes.length);
    bytes = newBytes;
}

