    if (size <= 0) {
        return;
    }
    int newCapacity = this.capacity + size;
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(this.buffer, 0, newBuffer, 0, this.capacity);
    this.buffer = newBuffer;
    this.capacity = newCapacity;
}

